const VS = 60.0;
fn st(c: vec2f) -> vec4f { return sampleTarget(0u, c); }
fn vel(c: vec2f) -> vec2f { return st(c).rg * VS; }
fn visual_fcb_sim(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let P = pix();
  // semi-Lagrangian advection
  let back = P - vel(P) * 1.0;
  var v = vel(back);
  var dye = st(back).b;
  // cheap divergence damping (incompressibility)
  let vL = vel(P + vec2f(-1.0, 0.0));
  let vR = vel(P + vec2f( 1.0, 0.0));
  let vD = vel(P + vec2f(0.0, -1.0));
  let vU = vel(P + vec2f(0.0,  1.0));
  let divg = 0.25 * ((vR.x - vL.x) + (vU.y - vD.y));
  v -= vec2f(vR.x - vL.x, vU.y - vD.y) * clamp(divg, -2.0, 2.0) * 0.06;
  // two swirling emitters (screen-space, canvas ~512)
  let t = time;
  let e1 = vec2f(180.0, 230.0);
  let e2 = vec2f(330.0, 300.0);
  let d1 = length(P - e1);
  let d2 = length(P - e2);
  v += vec2f( cos(t*1.1),  sin(t*1.1)) * exp(-d1*d1/1400.0) * 7.0;
  v += vec2f(-sin(t*0.8),  cos(t*0.8)) * exp(-d2*d2/1400.0) * 7.0;
  dye += (exp(-d1*d1/700.0) + exp(-d2*d2/700.0)) * 0.4;
  // kill NaN/Inf before they poison the feedback
  if (!(v.x==v.x) || !(v.y==v.y) || !(dye==dye)) { v = vec2f(0.0); dye = 0.0; }
  v = clamp(v * 0.990, vec2f(-VS), vec2f(VS));
  dye = clamp(dye * 0.960, 0.0, 1.3);
  // output IS state: rg = vel/VS, b = dye, a = 1 (alpha=1 -> overwrite the target)
  return vec4f(v / VS, dye, 1.0);
}

fn fcb_hsv(h: f32, s: f32, vv: f32) -> vec3f {
  let k = vec3f(1.0, 2.0/3.0, 1.0/3.0);
  let p = abs(fract(vec3f(h)+k)*6.0 - 3.0);
  return vv * mix(vec3f(1.0), clamp(p-1.0, vec3f(0.0), vec3f(1.0)), s);
}
fn fcb_dye(c: vec2f) -> f32 { return sampleTarget(0u, c).b; }
fn visual_fcb_view(uv: vec2f, sdf: f32, color: vec4f, time: f32, params: vec4f, behind: vec4f) -> vec4f {
  let P = pix();
  let s = sampleTarget(0u, P);
  let VS = 60.0;
  let v = s.rg * VS;
  let dye = s.b;
  let ch = i32(color.r * 10.0 + 0.5);
  if (ch == 0) { return vec4f(vec3f(dye), 1.0); }              // DEPTH: dye height
  if (ch == 1) {                                              // NORMAL: gradient of dye
    let hx = fcb_dye(P+vec2f(1.0,0.0)) - fcb_dye(P-vec2f(1.0,0.0));
    let hy = fcb_dye(P+vec2f(0.0,1.0)) - fcb_dye(P-vec2f(0.0,1.0));
    let n = normalize(vec3f(-hx, -hy, 0.15));
    return vec4f(n*0.5+0.5, 1.0);
  }
  if (ch == 2) {                                              // FLOW: analytic velocity colorwheel
    let ang = atan2(v.y, v.x) / 6.28318 + 0.5;
    let spd = clamp(length(v) / 18.0, 0.0, 1.0);
    return vec4f(fcb_hsv(ang, 0.9, 0.12 + 0.88*spd), 1.0);
  }
  var cols = array<vec3f,4>(vec3f(0.05,0.06,0.10), vec3f(0.90,0.30,0.25), vec3f(0.25,0.75,0.45), vec3f(0.30,0.55,0.95));
  var mat = 0;
  if (dye > 0.15) { mat = 1; }
  if (dye > 0.45) { mat = 2; }
  if (dye > 0.80) { mat = 3; }
  return vec4f(cols[mat], 1.0);
}
